fn is_ascii_digit(c: char) -> bool {
    // Requires: c is a valid char
    // Ensures: returns true if c is an ASCII digit ('0' to '9'), false otherwise
    assert!(c.is_ascii()); // Assert that c is an ASCII character
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Requires: s is a valid String
    // Ensures: returns true if all characters in s are ASCII digits, false otherwise
    // Invariant: For all characters in s, if c is a character in s, then is_ascii_digit(c) is true if and only if c is between '0' and '9'
    let mut result = true;
    for c in s.chars() {
        // Assert that c is an ASCII character
        assert!(c.is_ascii());
        result = result && is_ascii_digit(c);
    }
    result
}

